// Tier 2: one NFT per subdomain (TEP-62) + DNS resolver.
import "dns-utils"
import "errors"
import "messages"
import "storage"

contract SubdomainItem {
    author: "tolk-subdomains"
    version: "2.0.0"
    description: "Subdomain NFT item (TEP-62) holding its own DNS records."
    incomingMessages: AllowedItemMessage
    storage: ItemStorageInitialized
    storageAtDeployment: ItemStorageNotInitialized
}

type AllowedItemMessage =
    | TransferOwnership
    | EditContent
    | ChangeDnsRecord
    | GetStaticData

@inline
fun applyOwnershipTransfer(
    myBalance: coins,
    mutate storage: ItemStorageInitialized,
    queryId: uint64,
    transferData: TransferOwnershipData,
    fwdFees: coins,
) {
    val newOwnerAddress = transferData.newOwnerAddress;
    newOwnerAddress.forceBasechain();

    val responseDestination = transferData.responseDestination;
    val forwardAmount = transferData.forwardAmount;

    var restAmount = myBalance - MIN_TONS_FOR_STORAGE;
    if (forwardAmount > 0) {
        restAmount -= (forwardAmount + fwdFees);
    }
    val needResponse = responseDestination != null;
    if (needResponse) {
        restAmount -= fwdFees;
    }
    assert (restAmount >= 0) throw ERROR_INSUFFICIENT_BALANCE;

    if (forwardAmount > 0) {
        val assignMsg = createMessage({
            body: OwnershipAssigned {
                queryId,
                oldOwnerAddress: storage.ownerAddress,
                payload: transferData.forwardPayload,
            },
            bounce: false,
            dest: newOwnerAddress,
            value: forwardAmount,
        });
        assignMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
    }

    if (needResponse) {
        responseDestination!.forceBasechain();
        val excessesMsg = createMessage({
            body: Excesses { queryId },
            bounce: false,
            dest: responseDestination!,
            value: restAmount,
        });
        excessesMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
    }

    storage.ownerAddress = newOwnerAddress;
    storage.lastTouch = blockchain.now();
    storage.save();
}

// Every outbound item message is deliberately non-bounceable: ownership notifications and
// excesses are best-effort standard replies, so there is no item state to roll back on failure.
fun onBouncedMessage(_in: InMessageBounced) {}

fun onInternalMessage(in: InMessage) {
    val loading = startLoadingItemStorage();

    // ---------------- INIT ----------------
    if (!loading.isInitialized()) {
        val uninit = loading.parseNotInitialized();
        assert (in.senderAddress == uninit.collectionAddress) throw ERROR_NOT_FROM_COLLECTION;

        val init = lazy SubdomainInit.fromSlice(
            in.body,
            { throwIfOpcodeDoesNotMatch: ERROR_UNKNOWN_OP },
        );
        init.minter.forceBasechain();

        assert (init.index == uninit.index) throw ERROR_INDEX_MISMATCH;
        assert (init.label.load().hash() == uninit.index) throw ERROR_INDEX_MISMATCH;

        var records: DnsRecords = init.initialRecords != null ? init.initialRecords.load() : [];
        if (init.setWalletToMinter) {
            records.set(CAT_WALLET, buildWalletRecord(init.minter));
        }

        val now = blockchain.now();
        val initStorage: ItemStorageInitialized = {
            index: uninit.index,
            collectionAddress: uninit.collectionAddress,
            ownerAddress: init.minter,
            records: records.toCell(),
            label: init.label,
            mintedAt: now,
            lastTouch: now,
            validUntil: 0,
        };
        initStorage.save();
        return;
    }

    var storage = loading.parseInitialized();

    if (in.body.isEmpty()) {
        return;
    }

    if (in.body.remainingBitsCount() >= 32 && in.body.preloadUint(32) == 0xd53276db) {
        return;
    }

    var msg = lazy AllowedItemMessage.fromSlice(in.body);

    match (msg) {
        TransferOwnership => {
            assert (in.senderAddress == storage.ownerAddress) throw ERROR_NOT_OWNER;
            applyOwnershipTransfer(
                contract.getOriginalBalance(),
                mutate storage,
                msg.queryId,
                msg.transferData,
                in.originalForwardFee,
            );
        }

        EditContent => {
            assert (in.senderAddress == storage.ownerAddress) throw ERROR_NOT_OWNER;
            val validated = msg.newContent.load();
            storage.records = validated.toCell();
            storage.lastTouch = blockchain.now();
            storage.save();
        }

        ChangeDnsRecord => {
            assert (in.senderAddress == storage.ownerAddress) throw ERROR_NOT_OWNER;
            var dnsRecords = storage.records.load();
            if (msg.value.remainingRefsCount() > 0) {
                dnsRecords.set(msg.key, msg.value.loadRef());
            } else {
                dnsRecords.delete(msg.key);
            }
            storage.records = dnsRecords.toCell();
            storage.lastTouch = blockchain.now();
            storage.save();
        }

        GetStaticData => {
            val responseMsg = createMessage({
                body: ReportStaticData {
                    queryId: msg.queryId,
                    itemIndex: storage.index,
                    collectionAddress: storage.collectionAddress,
                },
                bounce: false,
                dest: in.senderAddress,
                value: 0,
            });
            responseMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }

        else => throw ERROR_UNKNOWN_OP,
    }
}

// =========================== getters ===========================

get fun get_nft_data(): ItemNftDataReply {
    val loading = startLoadingItemStorage();
    if (!loading.isInitialized()) {
        val st = loading.parseNotInitialized();
        return {
            isInitialized: false,
            index: st.index,
            collectionAddress: st.collectionAddress,
            ownerAddress: null,
            content: null,
        };
    }
    val st = loading.parseInitialized();
    return {
        isInitialized: true,
        index: st.index,
        collectionAddress: st.collectionAddress,
        ownerAddress: st.ownerAddress,
        content: st.label as cell,
    };
}

get fun get_editor(): address? {
    val loading = startLoadingItemStorage();
    if (!loading.isInitialized()) {
        return null;
    }
    return loading.parseInitialized().ownerAddress;
}

get fun get_domain(): slice {
    val loading = startLoadingItemStorage();
    if (!loading.isInitialized()) {
        return beginCell().endCell().beginParse();
    }
    return loading.parseInitialized().label.load();
}

get fun get_minted_at(): int {
    val loading = startLoadingItemStorage();
    return loading.isInitialized() ? loading.parseInitialized().mintedAt : 0;
}

get fun get_last_touch(): int {
    val loading = startLoadingItemStorage();
    return loading.isInitialized() ? loading.parseInitialized().lastTouch : 0;
}

get fun get_valid_until(): int {
    val loading = startLoadingItemStorage();
    return loading.isInitialized() ? loading.parseInitialized().validUntil : 0;
}

get fun dnsresolve(subdomain: slice, category: uint256): DnsResolveResponse {
    val subdomainBits = subdomain.remainingBitsCount();
    assertDnsQueryStartsWithZero(subdomain);

    val loading = startLoadingItemStorage();
    if (!loading.isInitialized()) {
        return { resolvedPrefixLengthBits: 0, resolvedRecord: null };
    }
    val st = loading.parseInitialized();
    val dnsRecord = st.records.load();

    if (subdomainBits > BYTE_SIZE) {
        category = CAT_DNS_NEXT_RESOLVER;
    }

    if (category == 0) {
        return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: dnsRecord.toLowLevelDict() };
    }

    val value = dnsRecord.get(category);
    if (!value.isFound) {
        return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: null };
    }
    return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: value.loadValue() };
}

// DNS helpers (TEP-81). Trimmed and adapted from the official acton-contracts/dns/dns-utils.tolk.
import "errors"

const BYTE_SIZE = 8

// https://github.com/ton-blockchain/ton/blob/master/crypto/block/block.tlb (dns_next_resolver#ba93)
const DNS_NEXT_RESOLVER_PREFIX = 0xba93

const MAX_DOMAIN_SIZE = 126 // minimum is per-registry (PriceConfig.minChars)

// TEP-81 dictionary keys are sha256(category-name), not raw category bytes.
const CAT_DNS_NEXT_RESOLVER = "dns_next_resolver".sha256()
const CAT_WALLET = "wallet".sha256()
const CAT_SITE = "site".sha256()
// Category name and TL-B value type are distinct: clients use sha256("storage") as the dictionary
// key, while dns_storage_address#7473 is the record VALUE tag.
const CAT_STORAGE = "storage".sha256()

fun address.forceBasechain(self) {
    assert (self.getWorkchain() == BASECHAIN) throw ERROR_WRONG_WORKCHAIN;
}

// dns_next_resolver#ba93 resolver:MsgAddressInt = DNSRecord
fun address.toNextResolver(self): cell {
    return beginCell().storeUint(DNS_NEXT_RESOLVER_PREFIX, 16).storeAddress(self).endCell();
}

// dns_smc_address#9fd3 smc_addr:MsgAddressInt flags:(## 8) ... = DNSRecord  (wallet record)
fun buildWalletRecord(wallet: address): cell {
    return beginCell().storeUint(0x9fd3, 16).storeAddress(wallet).storeUint(0, 8).endCell();
}

// Shared TEP-81 query-shape validation for collection and item resolvers.
fun dnsQueryStartsWithZero(subdomain: slice): bool {
    val bits = subdomain.remainingBitsCount();
    assert (bits >= BYTE_SIZE && bits % BYTE_SIZE == 0) throw ERROR_DNS_INVALID_SUBDOMAIN_BITS;
    return subdomain.preloadInt(BYTE_SIZE) == 0;
}

fun assertDnsQueryStartsWithZero(subdomain: slice) {
    assert (dnsQueryStartsWithZero(subdomain)) throw ERROR_DNS_INVALID_SUBDOMAIN_BITS;
}

fun getTopDomainBits(domain: slice): int {
    var bytes = domain;
    var bits = 0;
    var shouldStop = false;

    while (!shouldStop) {
        assert (bytes.remainingBitsCount() >= BYTE_SIZE) throw ERROR_DNS_INVALID_SUBDOMAIN_BITS;
        val ch = bytes.loadUint(BYTE_SIZE);
        shouldStop = ch == 0;
        if (!shouldStop) {
            bits += BYTE_SIZE;
        }
    }

    assert (bits > 0) throw ERROR_LABEL_TOO_SHORT;
    return bits;
}

enum DomainChar {
    Hyphen = 45
    DigitZero = 48
    DigitNine = 57
    LowercaseA = 97
    LowercaseZ = 122
}

// a-z / 0-9 / '-' (hyphen only in interior position, never first/last). `len` in bits.
@inline_ref
fun checkDomainString(domain: slice, len: int): bool {
    var bytes = domain;
    var i = 0;

    val charCount = len / BYTE_SIZE;
    val lastChar = charCount - 1;

    repeat (charCount) {
        val ch = bytes.loadUint(BYTE_SIZE);

        val isDigit = ch >= (DomainChar.DigitZero as int) && ch <= (DomainChar.DigitNine as int);
        val isLowercaseLetter = ch >= (DomainChar.LowercaseA as int) &&
        ch <= (DomainChar.LowercaseZ as int);

        var valid = isDigit || isLowercaseLetter;
        if (!valid) {
            valid = ch == (DomainChar.Hyphen as int) && i > 0 && i < lastChar;
        }
        if (!valid) {
            return false;
        }
        i += 1;
    }

    return true;
}

// Message bodies (opcode structs). Opcodes are crc32 (custom) or TEP-62 (reused).
import "storage"

type TransferForwardPayload = RemainingBitsAndRefs

// ---------------- TEP-62 (reused) ----------------
struct TransferOwnershipData {
    newOwnerAddress: address
    responseDestination: address?
    customPayload: cell?
    forwardAmount: coins
    forwardPayload: TransferForwardPayload
}

struct (0x5fcc3d14) TransferOwnership {
    queryId: uint64
    transferData: TransferOwnershipData
}

struct (0x05138d91) OwnershipAssigned {
    queryId: uint64
    oldOwnerAddress: address?
    payload: TransferForwardPayload
}

struct (0xd53276db) Excesses {
    queryId: uint64
}

struct (0x2fcb26a2) GetStaticData {
    queryId: uint64
}

struct (0x8b771735) ReportStaticData {
    queryId: uint64
    itemIndex: uint256
    collectionAddress: address
}

// ---------------- TEP-66 royalties ----------------
struct (0x693d3950) GetRoyaltyParams {
    queryId: uint64
}

struct (0xa8cb00ad) ReportRoyaltyParams {
    queryId: uint64
    numerator: uint16
    denominator: uint16
    destination: address
}

// ---------------- DNS records ----------------
struct (0x4eb1f0f9) ChangeDnsRecord {
    queryId: uint64
    key: uint256
    value: RemainingBitsAndRefs
}

struct (0x1a0b9d51) EditContent {
    queryId: uint64
    newContent: Cell<DnsRecords>
}

struct (0xba93) DnsNextResolver {
    resolver: address
}

// ---------------- Factory (Tier 0) ----------------
struct (0x6c0c4b17) LockCollection {
    deploymentId: uint64 = 0
    queryId: uint64
    parentDomain: address
    admin: address
    isLinked: bool
    meta: Cell<CollectionMeta>
}

// Authenticated collection deployment acknowledgement.
struct (0x52445931) CollectionReady {
    deploymentId: uint64
    queryId: uint64
    parentDomain: address
    admin: address
    currentAdmin: address
    isLinked: bool
    isNew: bool
}

// Confirms that the canonical parent completed a Locked handoff.
struct (0x48444f4b) ParentHandoffComplete {
    deploymentId: uint64
    queryId: uint64
    parentDomain: address
    intendedAdmin: address
}

// Recovery probe bound to a persisted handoff generation.
struct (0x48445052) ConfirmParentHandoff {
    deploymentId: uint64
    queryId: uint64
    parentDomain: address
    intendedAdmin: address
}

// Admin-funded replay of the factory's stored pending phase.
struct (0x52545259) RetryCollectionDeployment {
    queryId: uint64
    collectionAddress: address
}

// Linked create; the parent owner connects it later through next_resolver.
struct (0x4c494e4b) CreateLinkedCollection {
    queryId: uint64
    parentDomain: address
    admin: address
    meta: Cell<CollectionMeta>
}

// Generation proof forwarded through the parent during a Locked handoff.
struct (0x48414e44) FactoryHandoff {
    deploymentId: uint64 = 0
    requestQueryId: uint64 = 0
    intendedAdmin: address
}

// ---------------- Collection (Tier 1) ----------------
struct (0x2428aaa6) SubdomainInit {
    queryId: uint64
    index: uint256
    minter: address
    label: Cell<RemainingBitsAndRefs>
    setWalletToMinter: bool
    initialRecords: Cell<DnsRecords>?
}

struct (0x49278399) RegisterSubdomain {
    queryId: uint64
    label: Cell<RemainingBitsAndRefs> // bare label bytes, e.g. "alice" (no trailing \0)
    setWalletToMinter: bool
    initialRecords: Cell<DnsRecords>?
}

struct (0x7969d64e) SetContent {
    queryId: uint64
    meta: Cell<CollectionMeta>
}

struct (0x1e4b7535) WithdrawFees {
    queryId: uint64
    amount: coins // 0 means max
}

struct (0x2b8af82e) TransferAdmin {
    queryId: uint64
    newAdmin: address
}

struct (0x9f3acb9c) AdminAssigned {
    queryId: uint64
    prevAdmin: address
}

struct (0x97be5c56) ProxyEditParentRecord {
    queryId: uint64
    key: uint256
    value: RemainingBitsAndRefs
}

struct (0x5cfedae5) FillUpParent {
    queryId: uint64
}

struct (0xe0329a90) EnforceResolver {
    queryId: uint64
}

struct (0xccef6e14) SetLabelReserved {
    queryId: uint64
    labelHash: uint256
    reserved: bool
}

struct (0x2096dda6) RescueNft {
    queryId: uint64
    nftAddress: address
    toAddress: address
}

// Persistent storage + state loaders + deterministic address derivation.
import "dns-utils"
import "errors"
import "prices"

// ---- fee/economy constants ----
const MIN_TONS_FOR_STORAGE = ton("0.05")
const ITEM_DEPLOY_COST = ton("0.07")
const MINT_FEE_BUFFER = ton("0.03")
const COLLECTION_MIN_BALANCE = ton("0.05")
const COLLECTION_DEPLOY_VALUE = ton("0.25")
const FACTORY_READY_VALUE = ton("0.01")
const FACTORY_GAS_MARGIN = ton("0.01")
const RESOLVER_PIN_FUND = ton("0.1")
const MIN_CREATE_VALUE = ton("0.5")
const MIN_PARENT_FILL = ton("0.05") // min incoming value for a caller-funded parent renew
const FWD_FEE_RESERVE = ton("0.02")
const ONE_YEAR = 31622400
const PARENT_HEARTBEAT_INTERVAL = 86400 // 1 day
const PARENT_HEARTBEAT_AMOUNT = ton("0.01")

// ---- DNS records (TEP-81) ----
type DnsRecords = map<uint256, cell>

fun DnsRecords.packToBuilder(self, mutate b: builder) {
    b.storeUint(0, BYTE_SIZE);
    b.storeDict(self.toLowLevelDict());
}

fun DnsRecords.unpackFromSlice(mutate s: slice): DnsRecords {
    assert (s.loadUint(BYTE_SIZE) == 0) throw ERROR_CONTENT_TAG_INVALID;
    return createMapFromLowLevelDict<uint256, cell>(s.loadDict());
}

struct DnsResolveResponse {
    resolvedPrefixLengthBits: int
    resolvedRecord: cell?
}

// =========================== COLLECTION (Tier 1) ===========================

struct CollectionSkeleton {
    master: address
    parentDomain: address
    // Part of StateInit: Linked and Locked cannot pre-occupy each other's address.
    isLinked: bool
    // Creator binding prevents third-party pre-deployment of a Linked collection.
    linkedAdmin: address
}

struct CollectionMeta {
    priceConfig: Cell<PriceConfig>
    collectionContent: cell  // TEP-64 offchain (collection)
    itemContentBaseUri: cell // offchain prefix for items
}

struct CollectionOrigin {
    linkedAdmin: address
    isLinkedAtDeployment: bool
    lastFactoryHandoff: Cell<FactoryHandoffReceipt>?
}

// Receipt used to recover a lost factory handoff callback.
struct FactoryHandoffReceipt {
    deploymentId: uint64
    requestQueryId: uint64
    intendedAdmin: address
    returnRequired: bool
}

struct CollectionStorage {
    master: address
    parentDomain: address
    admin: address
    // Immutable address witness plus the latest handoff receipt.
    origin: Cell<CollectionOrigin>
    // true = Linked; false = terminal Locked custody.
    isLinked: bool
    lastParentFillUp: uint32
    meta: Cell<CollectionMeta>
    reserved: map<uint256, ()>
    minted: map<uint256, ()>
    mintedCount: uint32
}

fun CollectionStorage.save(self) {
    contract.setData(self.toCell());
}

struct CollectionLoader {
    cs: slice
}

fun startLoadingCollection(): CollectionLoader {
    return { cs: contract.getData().beginParse() };
}

fun CollectionLoader.isLocked(self): bool {
    return self.cs.remainingRefsCount() > 0;
}

fun CollectionLoader.parseSkeleton(self): CollectionSkeleton {
    return CollectionSkeleton.fromSlice(self.cs);
}

fun CollectionLoader.parseLocked(self): CollectionStorage {
    return CollectionStorage.fromSlice(self.cs);
}

struct CollectionDataReply {
    nextItemIndex: int
    content: cell
    ownerAddress: address?
}

// =========================== ITEM (Tier 2) ===========================

struct ItemStorageNotInitialized {
    index: uint256
    collectionAddress: address
}

struct ItemStorageInitialized {
    index: uint256
    collectionAddress: address
    ownerAddress: address
    records: Cell<DnsRecords>
    label: Cell<RemainingBitsAndRefs>
    mintedAt: uint32
    lastTouch: uint32
    validUntil: uint32 // 0 = perpetual (reserved)
}

fun ItemStorageInitialized.save(self) {
    contract.setData(self.toCell());
}

struct ItemLoader {
    cs: slice
}

fun startLoadingItemStorage(): ItemLoader {
    return { cs: contract.getData().beginParse() };
}

fun ItemLoader.isInitialized(self): bool {
    return self.cs.remainingRefsCount() > 0;
}

fun ItemLoader.parseNotInitialized(self): ItemStorageNotInitialized {
    return ItemStorageNotInitialized.fromSlice(self.cs);
}

fun ItemLoader.parseInitialized(self): ItemStorageInitialized {
    return ItemStorageInitialized.fromSlice(self.cs);
}

struct ItemNftDataReply {
    isInitialized: bool
    index: uint256
    collectionAddress: address
    ownerAddress: address?
    content: cell?
}

// =========================== deterministic derivation ===========================

fun calcDeployedItem(index: uint256, itemCode: cell): AutoDeployAddress {
    val skeleton: ItemStorageNotInitialized = { index, collectionAddress: contract.getAddress() };
    return { workchain: BASECHAIN, stateInit: { code: itemCode, data: skeleton.toCell() } };
}

fun calcDeployedCollection(
    master: address,
    parentDomain: address,
    isLinked: bool,
    linkedAdmin: address,
    collectionCode: cell,
): AutoDeployAddress {
    val skeleton: CollectionSkeleton = {
        master,
        parentDomain,
        isLinked,
        linkedAdmin,
    };
    return { workchain: BASECHAIN, stateInit: { code: collectionCode, data: skeleton.toCell() } };
}

// Pricing by label character count. Chosen at creation, immutable thereafter.
// One price per length: p1 (1-char) .. p10 (10-char), then pRest (11+). Short names are the most
// premium, so the grid is non-increasing. minChars gates the shortest mintable length.
// 11 coins fit one cell for any realistic price (even 10M TON/name is ~712 bits < 1023); the
// theoretical worst case (varuint16 max) is unreachable, so suppress the static overflow check.
@overflow1023_policy("suppress")
struct PriceConfig {
    minChars: uint8 // shortest allowed subdomain (1..4), chosen at creation, frozen
    p1: coins
    p2: coins
    p3: coins
    p4: coins
    p5: coins
    p6: coins
    p7: coins
    p8: coins
    p9: coins
    p10: coins
    pRest: coins    // 11+ chars
}

const MIN_NAME_PRICE = ton("0.05") // floor on the cheapest tier; rejects degenerate/zero grids at create
const MAX_MIN_CHARS = 4 // a registry may set its minimum to 1, 2, 3 or 4

// A grid is valid iff minChars is in range, prices are non-increasing by length, and the cheapest
// tier is above the floor.
fun PriceConfig.isValid(self): bool {
    return self.minChars >= 1 && self.minChars <= MAX_MIN_CHARS && self.p1 >= self.p2 &&
    self.p2 >= self.p3 &&
    self.p3 >= self.p4 &&
    self.p4 >= self.p5 &&
    self.p5 >= self.p6 &&
    self.p6 >= self.p7 &&
    self.p7 >= self.p8 &&
    self.p8 >= self.p9 &&
    self.p9 >= self.p10 &&
    self.p10 >= self.pRest &&
    self.pRest >= MIN_NAME_PRICE;
}

fun PriceConfig.priceForCharCount(self, n: int): coins {
    if (n <= 1) {
        return self.p1;
    }
    if (n == 2) {
        return self.p2;
    }
    if (n == 3) {
        return self.p3;
    }
    if (n == 4) {
        return self.p4;
    }
    if (n == 5) {
        return self.p5;
    }
    if (n == 6) {
        return self.p6;
    }
    if (n == 7) {
        return self.p7;
    }
    if (n == 8) {
        return self.p8;
    }
    if (n == 9) {
        return self.p9;
    }
    if (n == 10) {
        return self.p10;
    }
    return self.pRest; // 11+
}

// Default preset (4-char minimum). p1..p3 are premium tiers, unused at minChars 4 but kept monotonic.
fun defaultPriceConfig(): PriceConfig {
    return {
        minChars: 4,
        p1: ton("100"),
        p2: ton("50"),
        p3: ton("20"),
        p4: ton("10"),
        p5: ton("5"),
        p6: ton("4"),
        p7: ton("3"),
        p8: ton("2"),
        p9: ton("1"),
        p10: ton("0.5"),
        pRest: ton("0.1"),
    };
}
